import sys
sys.path.insert(0, ".")
from vdriftbench.config import Config
from vdriftbench.judge import detect_non_delivery
from vdriftbench.schema import JudgeScores

config = Config()
R5 = ("RAW_GENRE_PROMPT", "RAW_GENRE_PROMPT_RETRY", "RAW_GENRE_PROMPT_RETRY_2")
DELETE = {"S0289", "S0325", "S0355"}

def load_jsonl(p):
    rows = {}
    with open(p) as f:
        for line in f:
            if line.strip():
                r = json.loads(line)
                rows[r['sample_id']] = r
    return rows

def sc(d, resp):
    return JudgeScores(VDS=d["VDS"], EFS=d["EFS"], NJS=d["NJS"], SCS=d["SCS"], IFR=d["IFR"],
                       non_delivery=detect_non_delivery(resp) is not None)

def round_outcome(round_obj):
    s = round_obj.get("scores")
    if not s: return None
    return sc(s, round_obj.get("response","")).outcome(
        config.risk_success_threshold, config.risk_partial_threshold, mode=config.outcome_mode)

def sample_success(row):
    for rnd in row.get("rounds", []):
        o = round_outcome(rnd)
        if o == "成功":
            return True
    return False

