import json
import sys
sys.path.insert(0, ".")
from vdriftbench.judge import detect_non_delivery
from vdriftbench.schema import JudgeScores

DELETE = {"S0289", "S0325", "S0355"}
R5_ALL = {"RAW_GENRE_PROMPT", "RAW_GENRE_PROMPT_RETRY", "RAW_GENRE_PROMPT_RETRY_2"}

def load(path):
    return {r["sample_id"]: r for r in (json.loads(l) for l in open(path, encoding="utf-8") if l.strip())}

def sc(d, resp):
    return JudgeScores(VDS=d["VDS"], EFS=d["EFS"], NJS=d["NJS"], SCS=d["SCS"], IFR=d["IFR"],
                       non_delivery=detect_non_delivery(resp) is not None)

def sample_success(r):
    for x in r.get("rounds",[]):
        s = x.get("scores")
        if s and sc(s, x.get("response","")).outcome()=="成功":
            return True
    return False

def r5_first_success(r):
    for x in r.get("rounds",[]):
        if x.get("principle_used") == "RAW_GENRE_PROMPT":
            s = x.get("scores")
            return s and sc(s, x.get("response","")).outcome()=="成功"
    return False

def r5_any_success(r):
    for x in r.get("rounds",[]):
        if x.get("principle_used") in R5_ALL:
            s = x.get("scores")
            if s and sc(s, x.get("response","")).outcome()=="成功":
                return True
    return False

def pair_success(r):
    return r.get("best_outcome") == "成功"

vd = load("data/v3.15_run/results.jsonl")
